#!/usr/bin/env python3
"""Compute numeric threshold ledger ground truth for CSX-260_Q2."""

from __future__ import annotations

import datetime as dt
import html
import json
import re
from pathlib import Path
from typing import Any


TASK_ID = "CSX-260_Q2"
EVENT_ID = "CSX-260"
PACKAGE_RELATIVE_PATH = Path("event_packages") / "standard_event_packages" / "packages" / EVENT_ID

SOURCE_FILES = [
    "metadata/event.json",
    "data/event_reports/event_reports_003_Locked_event_anchor_July_2021_Western_Europe_extreme_rainfall_and_flood_disaster.json",
    "data/event_reports/event_reports_002_Package_locked_anchor.html",
    "data/event_catalogs/event_catalogs_001_GDACS_disaster_alert_API.json",
    "data/physical_hazard/physical_hazard_001_Open-Meteo_daily_weather_fill.json",
    "data/physical_hazard/physical_hazard_002_NASA_POWER_daily_weather_fill.json",
    "data/physical_hazard/physical_hazard_003_ERA5-Land_hourly_aggregate_stats.json",
    "data/physical_hazard/physical_hazard_004_GPM_IMERG_V07_event_accumulated_precipitation.json",
    "data/exposure_impact/exposure_impact_002_WorldPop_GP_100m_population_sum.json",
    "data/physical_hazard/physical_hazard_006_Sentinel-2_SR_Harmonized_dNBR.json",
    "data/remote_sensing/remote_sensing_003_Google_Satellite_Embedding_annual_cosine-change_stats.json",
]

RUBRIC = {
    "total_points": 20,
    "criteria": [
        {
            "name": "Answer shape",
            "points": 3,
            "description": "Returns compact JSON with ledger_values, gates, and label, using the requested field names and units.",
        },
        {
            "name": "Window and point rainfall",
            "points": 4,
            "description": "Counts the 6-day inclusive window and computes point_total_mean_mm = 22.6 and point_peak_share_mean = 0.582 within tolerance.",
        },
        {
            "name": "Gridded rainfall comparison",
            "points": 3,
            "description": "Computes grid_mean_mm = 33.7 and grid_spread_ratio = 2.136 from the two available gridded event means.",
        },
        {
            "name": "Catalog and exposure checks",
            "points": 3,
            "description": "Counts 2 overlapping Germany or Belgium flood alerts and reports worldpop_millions = 1.025.",
        },
        {
            "name": "Remote-change countercheck",
            "points": 3,
            "description": "Computes remote_context_index = 0.134 from dNBR mean and embedding-change mean, and treats it as contextual rather than a direct flood-depth measure.",
        },
        {
            "name": "Threshold result and bounded interpretation",
            "points": 4,
            "description": "Applies all seven gates, reports pass_count = 7 and label rainfall_flood_window_consistent, and avoids adding unsupported depth, loss-total, or attribution values.",
        },
    ],
}


def repo_root() -> Path:
    return Path(__file__).resolve().parents[3]


def package_dir() -> Path:
    return repo_root() / PACKAGE_RELATIVE_PATH


def task_dir() -> Path:
    return Path(__file__).resolve().parent


def load_json(relative_path: str) -> dict[str, Any]:
    with (package_dir() / relative_path).open("r", encoding="utf-8") as handle:
        return json.load(handle)


def read_text(relative_path: str) -> str:
    with (package_dir() / relative_path).open("r", encoding="utf-8", errors="ignore") as handle:
        return handle.read()


def parse_date(value: str) -> dt.date:
    if "T" in value:
        value = value.split("T", 1)[0]
    return dt.date.fromisoformat(value)


def in_window(date_text: str, start: dt.date, end: dt.date) -> bool:
    date_value = parse_date(date_text)
    return start <= date_value <= end


def finite(value: Any) -> float:
    if isinstance(value, (int, float)):
        return float(value)
    raise TypeError(f"Expected finite numeric value, got {value!r}")


def summarize_daily(rows: list[dict[str, Any]]) -> dict[str, Any]:
    values = [finite(row["precip_mm"]) for row in rows]
    total = sum(values)
    peak = max(values)
    peak_row = max(rows, key=lambda row: finite(row["precip_mm"]))
    return {
        "sum_mm": round(total, 2),
        "peak_mm": round(peak, 2),
        "peak_date": peak_row["date"],
        "wet_days_ge_1mm": sum(1 for value in values if value >= 1.0),
        "peak_share": round(peak / total, 3),
        "rows": rows,
    }


def daily_open_meteo(data: dict[str, Any], start: dt.date, end: dt.date) -> dict[str, Any]:
    rows = []
    dates = data["daily"]["time"]
    values = data["daily"]["precipitation_sum"]
    for date_text, value in zip(dates, values):
        if in_window(date_text, start, end):
            rows.append({"date": date_text, "precip_mm": finite(value)})
    return summarize_daily(rows)


def daily_nasa_power(data: dict[str, Any], start: dt.date, end: dt.date) -> dict[str, Any]:
    rows = []
    precipitation = data["properties"]["parameter"]["PRECTOTCORR"]
    for date_key, value in precipitation.items():
        date_text = f"{date_key[0:4]}-{date_key[4:6]}-{date_key[6:8]}"
        if in_window(date_text, start, end):
            rows.append({"date": date_text, "precip_mm": finite(value)})
    rows.sort(key=lambda row: row["date"])
    return summarize_daily(rows)


def overlapping_flood_alerts(catalog: dict[str, Any], start: dt.date, end: dt.date) -> list[dict[str, Any]]:
    target_countries = {"Belgium", "Germany"}
    alerts = []
    for feature in catalog.get("features", []):
        properties = feature.get("properties", {})
        if properties.get("eventtype") != "FL":
            continue
        country_text = str(properties.get("country", ""))
        affected = {
            item.get("countryname", "")
            for item in properties.get("affectedcountries", [])
            if isinstance(item, dict)
        }
        if not (country_text in target_countries or affected & target_countries):
            continue
        from_date = parse_date(properties["fromdate"])
        to_date = parse_date(properties["todate"])
        if from_date <= end and to_date >= start:
            alerts.append(
                {
                    "country": country_text,
                    "alertlevel": properties.get("alertlevel"),
                    "fromdate": properties.get("fromdate"),
                    "todate": properties.get("todate"),
                }
            )
    return sorted(alerts, key=lambda item: (item["country"], item["fromdate"]))


def population_sum(data: dict[str, Any]) -> int:
    value = data.get("population_sum")
    if isinstance(value, dict) and isinstance(value.get("population"), (int, float)):
        return int(round(float(value["population"])))
    if isinstance(value, (int, float)):
        return int(round(float(value)))
    raise KeyError("population_sum.population not found")


def report_flags(report_html: str) -> dict[str, bool]:
    text = html.unescape(re.sub(r"<[^>]+>", " ", report_html)).lower()
    return {
        "flash_flood_text": bool(re.search(r"flash floods?|floodwaters?|flooding", text)),
        "extreme_rainfall_text": "extreme july rainfall" in text or "intense rain" in text,
        "life_safety_text": bool(re.search(r"killed|injured|missing|evacuat", text)),
        "river_or_dam_text": bool(re.search(r"rivers?|dam", text)),
    }


def main() -> None:
    metadata = load_json(SOURCE_FILES[0])
    anchor = load_json(SOURCE_FILES[1])
    start = parse_date(anchor["temporal_window"]["start_date"])
    end = parse_date(anchor["temporal_window"]["end_date"])
    window_days = (end - start).days + 1

    report = read_text(SOURCE_FILES[2])
    gdacs = load_json(SOURCE_FILES[3])
    open_meteo = daily_open_meteo(load_json(SOURCE_FILES[4]), start, end)
    nasa_power = daily_nasa_power(load_json(SOURCE_FILES[5]), start, end)
    era5_mean = finite(load_json(SOURCE_FILES[6])["stats"]["precipitation_sum_mm_mean"])
    gpm_mean = finite(load_json(SOURCE_FILES[7])["stats"]["gpm_event_precip_mm_mean"])
    population = population_sum(load_json(SOURCE_FILES[8]))
    dnbr_mean = finite(load_json(SOURCE_FILES[9])["stats"]["sentinel2_dnbr_mean"])
    embedding_mean = finite(load_json(SOURCE_FILES[10])["stats"]["alphaearth_1_minus_cosine_mean"])
    alerts = overlapping_flood_alerts(gdacs, start, end)

    point_total_mean_mm = round((open_meteo["sum_mm"] + nasa_power["sum_mm"]) / 2.0, 1)
    point_peak_share_mean = round((open_meteo["peak_share"] + nasa_power["peak_share"]) / 2.0, 3)
    grid_mean_mm = round((era5_mean + gpm_mean) / 2.0, 1)
    grid_spread_ratio = round(max(era5_mean, gpm_mean) / min(era5_mean, gpm_mean), 3)
    gdacs_flood_alerts = len(alerts)
    worldpop_millions = round(population / 1_000_000.0, 3)
    remote_context_index = round((abs(dnbr_mean) + embedding_mean) / 2.0, 3)

    ledger_values = {
        "window_days": window_days,
        "point_total_mean_mm": point_total_mean_mm,
        "point_peak_share_mean": point_peak_share_mean,
        "grid_mean_mm": grid_mean_mm,
        "grid_spread_ratio": grid_spread_ratio,
        "gdacs_flood_alerts": gdacs_flood_alerts,
        "worldpop_millions": worldpop_millions,
        "remote_context_index": remote_context_index,
    }
    gates = {
        "window_6d": window_days == 6,
        "point_total_ge_20mm": point_total_mean_mm >= 20.0,
        "point_peak_share_ge_0_55": point_peak_share_mean >= 0.55,
        "grid_mean_ge_30mm": grid_mean_mm >= 30.0,
        "gdacs_alerts_ge_2": gdacs_flood_alerts >= 2,
        "population_ge_1m": worldpop_millions >= 1.0,
        "remote_context_lt_0_20": remote_context_index < 0.20,
    }
    pass_count = sum(1 for value in gates.values() if value)
    ledger_values["pass_count"] = pass_count
    label = "rainfall_flood_window_consistent" if pass_count == len(gates) else "partial_flood_window_record"

    result = {
        "schema_version": "1.0",
        "task_id": TASK_ID,
        "event_id": EVENT_ID,
        "task_type": "numeric",
        "target_family": "western_europe_flood_window_threshold_ledger",
        "evaluation_mode": "deterministic",
        "evaluation_mode_justification": "All fields are deterministic date counts, arithmetic summaries, alert filtering, and threshold tests from local package data.",
        "difficulty_level": "L3",
        "event": {
            "package_id": EVENT_ID,
            "event_name": metadata["event_name"],
            "hazard_family": metadata["hazard_family"],
            "span_start": str(start),
            "span_end": str(end),
        },
        "primary_gt": {
            "answer": label,
            "ledger_values": ledger_values,
            "gates": gates,
            "tolerances": {
                "window_days": 0,
                "point_total_mean_mm": 0.05,
                "point_peak_share_mean": 0.002,
                "grid_mean_mm": 0.05,
                "grid_spread_ratio": 0.002,
                "counts": 0,
                "worldpop_millions": 0.001,
                "remote_context_index": 0.001,
            },
        },
        "key_values": {
            "daily_point_summaries": {
                "open_meteo": open_meteo,
                "nasa_power": nasa_power,
            },
            "gridded_precipitation_means_mm": {
                "era5_land": round(era5_mean, 3),
                "gpm_imerg": round(gpm_mean, 3),
            },
            "gdacs_alerts": alerts,
            "worldpop_population": population,
            "remote_change_means": {
                "sentinel2_dnbr_mean": round(dnbr_mean, 3),
                "embedding_1_minus_cosine_mean": round(embedding_mean, 3),
            },
            "report_flags": report_flags(report),
            "label_rule": "rainfall_flood_window_consistent when all seven gates are true; otherwise partial_flood_window_record",
        },
        "rubric": RUBRIC,
        "provenance": {
            "computed_by": "compute_gt.py",
            "source_files": SOURCE_FILES,
        },
        "requires_computation": True,
    }

    (task_dir() / "computed_gt.json").write_text(
        json.dumps(result, ensure_ascii=True, indent=2, sort_keys=True) + "\n",
        encoding="utf-8",
    )


if __name__ == "__main__":
    main()
